  const yearTranslations=root.CM_YEAR_TRANSLATIONS||(root.CM_YEAR_TRANSLATIONS={});Object.assign(yearTranslations,translations);

  function homeFor(id){return homes[id]||null;}
  function variant(prop,year){let out={name:prop.name,look:prop.look,story:prop.story};for(const v of prop.variants||[])if(year>=v.from)out={name:v.name||out.name,look:v.look||out.look,story:v.story||out.story};return out;}
  function fill(text,year){const y=Math.max(1,Math.min(10,Number(year)||1));return String(text||'').replace(/\{older\}/g,String(y+3)).replace(/\{younger\}/g,String(y));}
  function propText(residentId,prop,year,lang){const v=variant(prop,year),pick=value=>fill(value?.[lang==='en'?'en':'zh']||value?.zh||'',year);return {name:pick(v.name),look:pick(v.look),story:pick(v.story)};}
  function refusal(id,index){const list=refusals[id]||[];return list.length?list[((Number(index)||0)%list.length+list.length)%list.length]:null;}
  function hintsFor(caseKey,prop){if(!caseKey||!prop?.hints?.length)return false;return caseKey.startsWith('visit-')?true:prop.hints.includes(caseKey);}
  root.CM_YEAR_CONTENT=Object.freeze({households:HOUSEHOLDS,plural:PLURAL,refusals,homes,voiceNeed,patience,openers,teaser,homeFor,propText,refusal,hintsFor,pair});
